// Accept the attempt id from the body OR the query string; refuse to forward anything missing,
// malformed or contradictory. Server-side binding is unchanged.
const raw = $json.body || $json;
const body = (raw && typeof raw === 'object') ? raw : {};
const query = ($json.query && typeof $json.query === 'object') ? $json.query : {};
const has = (v) => v !== undefined && v !== null && String(v).trim() !== '';
const bodyId = has(body.attemptId) ? String(body.attemptId).trim() : null;
const queryId = has(query.attemptId) ? String(query.attemptId).trim() : null;

if (bodyId && queryId && bodyId !== queryId) {
  return [{ json: { ok: false, status: 400, error: 'CONFLICTING_ATTEMPT_ID' } }];
}
const attemptId = bodyId || queryId;
if (!attemptId || !/^att_[a-f0-9]{24}$/.test(attemptId)) {
  return [{ json: { ok: false, status: 400, error: 'MALFORMED' } }];
}
return [{ json: {
  ok: true,
  timestamp: String(Math.floor(Date.now() / 1000)),
  body: Object.assign({}, body, { attemptId })
} }];

// Pass the server's JSON through unchanged when it succeeded; otherwise give Rosina a
// line that is honest about the answer not being recorded.
const FAILED = "Thank you. I couldn't confirm your answer was recorded. If this is time-sensitive, please contact the family directly.";
const r = $json || {};
const status = Number(r.statusCode || 0);
let payload = r.body;
if (typeof payload === 'string') { try { payload = JSON.parse(payload) } catch { payload = null } }
if (status >= 200 && status < 300 && payload && typeof payload.say === 'string') {
  return [{ json: payload }];
}
return [{ json: { status: 'FAILED', note: 'voice_turn_unavailable', say: FAILED } }];
